  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00241",
          "explanation": "Doctor explicitly repairs the result-review responsibility chain by directing the family to ask for the responsible doctor or duty doctor and confirm ownership/timing.",
          "quote": "让家属知道今天这件事有人负责"
        }
      ],
      "completion": "complete",
      "explanation": "Triggered by uncertainty about whether new results had been reviewed. The doctor moved the family from self-judgment to nurse-station escalation and responsible-doctor review, which led to later bedside explanation.",
